{"command":"kubectl patch deployment app -n default --type='merge' -p '
{
  "spec": {
    "template": {
      "spec": {
        "volumes": [
          {
            "name": "nginx-cache",
            "emptyDir": {}
          }
        ],
        "containers": [
          {
            "name": "app",
            "volumeMounts": [
              {
                "name": "nginx-cache",
                "mountPath": "/var/cache/nginx"
              }
            ]
          }
        ]
      }
    }
  }
}'
"}

